            if let v = o["cache"], v != .null { self.cache = try Cache(json: v, path: path + ".cache") } else { self.cache = nil }
            if let v = o["binds"], v != .null { self.binds = try v.asArray(path + ".binds").enumerated().map { try Bind(json: $1, path: path + "[\($0)]") } } else { self.binds = nil }
            if let v = o["chrome"], v != .null { self.chrome = try ChromeBody(json: v, path: path + ".chrome") } else { self.chrome = nil }
            if let v = o["view"], v != .null { self.view = try ViewBody(json: v, path: path + ".view") } else { self.view = nil }
        }
        var json: JSONValue {
